import socket, urllib.request
for host in ['github.com','agentskills.io','raw.githubusercontent.com']:
    try:
        print(host,'DNS ->', socket.gethostbyname(host))
    except Exception as e:
        print(host,'DNS_FAIL', type(e).__name__, e)
for url in ['https://github.com/langchain-ai/deepagents','https://agentskills.io/specification']:
    try:
        req=urllib.request.Request(url, headers={'User-Agent':'Mozilla/5.0'})
        r=urllib.request.urlopen(req, timeout=15)
        print(url,'OK',r.status,len(r.read()))
    except Exception as e:
        print(url,'FAIL',type(e).__name__,e)
EOF
